CREATE TABLE IF NOT EXISTS hrm_payroll_financial_plan (id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY, entity_id bigint, prior_plan_id bigint, year int, month int, version int, dimension varchar(32), dimension_key varchar(100), evidence varchar(1000), source_reference varchar(200),
 status varchar(32), request_key varchar(100), request_snapshot LONGTEXT, review_reason varchar(1000), budget decimal(20,2), revenue decimal(20,2), headcount decimal(12,4), submitted_by bigint, reviewed_by bigint, reviewed_time datetime, creator varchar(64) DEFAULT '', create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, updater varchar(64) DEFAULT '', update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted bit NOT NULL DEFAULT FALSE, tenant_id bigint NOT NULL DEFAULT 0, UNIQUE KEY uk_financial_request(tenant_id,request_key), UNIQUE KEY uk_financial_version(tenant_id,entity_id,year,month,dimension,dimension_key,version), active_scope varchar(255) GENERATED ALWAYS AS (CASE WHEN deleted=b'0' AND status='APPROVED' THEN CONCAT(entity_id,':',year,':',month,':',dimension,':',dimension_key) ELSE NULL END) STORED, UNIQUE KEY uk_financial_active(tenant_id,active_scope)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS hrm_payroll_financial_event (id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY, entity_id bigint, plan_id bigint, actor_id bigint, year int, month int, action varchar(32), reason varchar(1000), snapshot LONGTEXT, creator varchar(64) DEFAULT '', create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, updater varchar(64) DEFAULT '', update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted bit NOT NULL DEFAULT FALSE, tenant_id bigint NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SET @parent=(SELECT id FROM system_menu WHERE path='/hrm-payroll' AND deleted=0 LIMIT 1);
INSERT INTO system_menu(name,permission,type,parent_id,path,icon,component,component_name) SELECT '预算与成本分析','hrm:payroll:analysis:query',2,@parent,'analysis','ep:histogram','hrm/payroll/analysis/index','HrmPayrollAnalysis' WHERE @parent IS NOT NULL AND NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='hrm:payroll:analysis:query' AND deleted=0);
SET @analysis=(SELECT id FROM system_menu WHERE permission='hrm:payroll:analysis:query' AND deleted=0 LIMIT 1);
INSERT INTO system_menu(name,permission,type,parent_id,path,icon,component,component_name) SELECT '预算营收编制维护','hrm:payroll:analysis:update',3,@analysis,'','','','' WHERE @analysis IS NOT NULL AND NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='hrm:payroll:analysis:update' AND deleted=0);
INSERT INTO system_menu(name,permission,type,parent_id,path,icon,component,component_name) SELECT '计划独立复核','hrm:payroll:analysis:approve',3,@analysis,'','','','' WHERE @analysis IS NOT NULL AND NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='hrm:payroll:analysis:approve' AND deleted=0);
INSERT INTO system_menu(name,permission,type,parent_id,path,icon,component,component_name) SELECT '分析与模板导出','hrm:payroll:analysis:export',3,@analysis,'','','','' WHERE @analysis IS NOT NULL AND NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='hrm:payroll:analysis:export' AND deleted=0);
